// 10 张合成占位 JPEG（base64，无 data: 前缀；360x520 渐变底 + 编号 + MOCK 字样），page/thumb 与 page/lab/run/image 用。
// 生成脚本不随本仓库提供；换图直接替换下面的 base64 字符串即可。
export const PLACEHOLDER_JPEGS = [
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
]

/** 文件名 → 稳定的一张占位图，保证同一张图每次刷新都长一样。 */
export function jpegFor(name) {
  let h = 0
  for (const ch of String(name || "")) h = (h * 31 + ch.charCodeAt(0)) >>> 0
  return PLACEHOLDER_JPEGS[h % PLACEHOLDER_JPEGS.length]
}
